input.script:
companies = list_companies({})
first = boundary retry 2 {
    return list_contacts({ page: 1 })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_contacts({ page }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
contacts = fold acc = first.items for page in remaining { return acc + page }
by_domain = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}
results = for contact in contacts {
    phone = contact.phone if contact.phone != null else ""
    valid = regex.test(phone, "^\\+1[0-9]{10}$")
    digits = regex.replace(phone, "[^0-9]", "")
    new_phone = if valid {
        return null
    } else if text.length(digits) == 10 {
        return "+1" + digits
    } else if text.length(digits) == 11 and text.starts_with(digits, "1") {
        return "+" + digits
    } else {
        return null
    }
    domain = if contact.email != null and "@" in contact.email {
        return text.split(contact.email, "@")[1]
    } else {
        return ""
    }
    needs_company = contact.company == null or contact.company == ""
    new_company = if needs_company and domain != "" and domain in by_domain {
        return by_domain[domain]
    } else {
        return null
    }
    phone_changed = new_phone != null
    company_changed = new_company != null
    u = update_contact({ id: contact.id, phone: new_phone, company: new_company }) if phone_changed or company_changed
    return { phone_fixed: phone_changed, company_filled: company_changed }
}
phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}
submitted = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed: phones_fixed, companies_filled: companies_filled, submitted: submitted }
